#!/usr/bin/env python3
"""Builds podcast_script_nationalite{,_fr,_de,_lb}.md from build/nationalite_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "nationalite"
HEAD = {
 "en": ('# Podcast Script — "Becoming Luxembourgish – How to Get the Nationality"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « Devenir luxembourgeois – Comment obtenir la nationalité »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Luxemburger werden – Wie man die Staatsangehörigkeit bekommt“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „Lëtzebuerger ginn – Wéi een d'Nationalitéit kritt“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 10, "fr": 9, "de": 11, "lb": 10}   # EN 10:14, FR 9:25, DE 11:04 (27 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources: guichet.public.lu (Guichet.lu, the State's information portal), consulted on 27 November 2026 in English and French — \"Obtaining Luxembourgish nationality by simple operation of law\" (parent Luxembourgish at birth; minor whose parent becomes Luxembourgish; born in Luxembourg to a parent also born in Luxembourg; born in Luxembourg to foreign parents: Luxembourgish at 18 after 5 consecutive years of legal residence, plus, for those born after 1 July 2013, 12 months of a parent's residence before the birth); \"Acquiring Luxembourgish nationality by naturalisation\" (adults, 5 years of legal residence with the last year uninterrupted; language test; \"Vivre ensemble au Grand-Duché de Luxembourg\" course or test; good repute; in person at the civil registrar of the commune; birth certificate, passport, biographical questionnaire, foreign criminal records; 3 months to complete a file; translations by a sworn translator if not in French, German, English or Luxembourgish; decision of the Minister of Justice within 8 months, by post as a rule; effect on the date of the ministerial order; free of charge); \"Acquiring Luxembourgish nationality by option\" (10 cases; conditions per case; commune of residence, City of Luxembourg for people living abroad; nationality 4 months after the Ministry receives the file if there is no objection; free of charge); \"Prerequisites for voluntary acquisition of nationality\" (Sproochentest Lëtzebuergesch by the National Institute for Languages Luxembourg, online registration, speaking A2, listening B1, listening can offset speaking; 24-hour course in 3 modules; course or test, free online registration; medical exemptions; automatic exemption from the history module with the certificate of the minimum 6-hour overview module of the Biergerpakt, the citizens' pact for intercultural living together; 24-hour Luxembourgish course for the 20-year option case; refund of the registration fees on request to the Ministry of Justice after the nationality application); \"Reclaiming Luxembourgish nationality\" (adults who lost the nationality; women who lost it through marriage; descendants of an ancestor who was Luxembourgish on 1 January 1900: last listed date 31 December 2025); \"Linguistic leave\" (employees and self-employed people; 200 hours over a career in 2 parts of 80 to 120 hours; no age or residence condition); \"Citizen's pact for intercultural living together – Biergerpakt\" (3 introductory modules to life in Luxembourg). The biographical questionnaire form (guichet.public.lu): ask the authorities of the country of origin whether the other nationality can be kept. Nationality Office of the Ministry of Justice (mj.gouvernement.lu). Durable wording only: no fees (the language test fee is on Guichet.lu), no phone numbers, no opening hours, no statistics. Voting is explained in the episode I Can Vote. General information only; only the legal texts are binding. Accurate as of November 2026.*",
 "fr": "*Sources : guichet.public.lu (Guichet.lu, le portail d'information de l'État), consulté le 27 novembre 2026 en anglais et en français — « Obtenir la nationalité luxembourgeoise par le seul effet de la loi » (filiation ; mineur dont le parent devient luxembourgeois ; double droit du sol ; enfant né au Luxembourg de parents étrangers : luxembourgeois à 18 ans après 5 années consécutives de résidence légale, et, pour les enfants nés après le 1er juillet 2013, 12 mois de résidence d'un parent avant la naissance) ; « Acquérir la nationalité luxembourgeoise par naturalisation » (majeur, 5 ans de résidence légale dont la dernière année ininterrompue ; examen d'évaluation de la langue luxembourgeoise ; cours ou examen « Vivre ensemble au Grand-Duché de Luxembourg » ; condition d'honorabilité ; en personne chez l'officier de l'état civil de la commune ; acte de naissance, passeport, notice biographique, extraits de casier judiciaire étrangers ; 3 mois pour compléter le dossier ; traduction par un traducteur assermenté si le document n'est pas en français, allemand, anglais ou luxembourgeois ; décision du ministre de la Justice dans les 8 mois ; gratuit) ; « Acquérir la nationalité luxembourgeoise par option » (10 cas ; commune de résidence, Ville de Luxembourg pour les personnes vivant à l'étranger ; nationalité 4 mois après réception par le ministère sans opposition ; gratuit) ; « Conditions préalables à l'acquisition volontaire de la nationalité » (Sproochentest auprès de l'Institut national des langues Luxembourg, niveaux A2 et B1, compensation ; cours de 24 heures en 3 modules ; dispenses médicales ; dispense automatique du module d'histoire avec le certificat du module d'au moins 6 heures du Biergerpakt, le pacte citoyen du vivre-ensemble interculturel ; remboursement des frais d'inscription sur demande au ministère de la Justice) ; « Recouvrement de la nationalité luxembourgeoise » (dernière date pour les descendants : 31 décembre 2025) ; « Congé linguistique » (200 heures sur la carrière, 2 tranches ; aucune condition d'âge ou de résidence) ; « Pacte citoyen du vivre-ensemble interculturel – Biergerpakt ». Notice biographique : se renseigner auprès des autorités du pays d'origine sur la conservation de la nationalité. Service de la nationalité luxembourgeoise du ministère de la Justice (mj.gouvernement.lu). Formulations durables uniquement : pas de tarifs, pas de numéros de téléphone, pas d'horaires, pas de statistiques. Le vote est expliqué dans l'épisode « Je peux voter ». Informations générales uniquement ; seuls les textes légaux font foi. Exact en novembre 2026.*",
 "de": "*Quellen: guichet.public.lu (Guichet.lu, das Informationsportal des Staates), abgerufen am 27. November 2026 auf Englisch und Französisch — „Luxemburgische Staatsangehörigkeit kraft Gesetzes“ (Abstammung; Minderjährige, deren Elternteil Luxemburger wird; doppeltes Geburtsortprinzip; in Luxemburg geborene Kinder ausländischer Eltern: Luxemburger mit 18 nach 5 aufeinanderfolgenden Jahren rechtmäßigen Aufenthalts, und für nach dem 1. Juli 2013 Geborene 12 Monate Aufenthalt eines Elternteils vor der Geburt); „Einbürgerung“ (Volljährige, 5 Jahre rechtmäßiger Aufenthalt, das letzte Jahr ohne Unterbrechung; Sprachtest Luxemburgisch; Kurs oder Prüfung „Vivre ensemble au Grand-Duché de Luxembourg“; guter Leumund; persönlich beim Standesbeamten der Gemeinde; Geburtsurkunde, Pass, biografische Angaben, ausländische Strafregisterauszüge; 3 Monate zur Vervollständigung; Übersetzung durch einen vereidigten Übersetzer; Entscheidung des Justizministers innerhalb von 8 Monaten; kostenlos); „Option“ (10 Fälle; Wohngemeinde, Stadt Luxemburg für Menschen im Ausland; Staatsangehörigkeit 4 Monate nach Eingang im Ministerium ohne Einwand; kostenlos); „Voraussetzungen“ (Sproochentest beim Nationalen Spracheninstitut Luxemburg, Niveaus A2 und B1, Ausgleich; Kurs von 24 Stunden in 3 Modulen; ärztliche Befreiungen; automatische Befreiung vom Geschichtsmodul mit der Bescheinigung des mindestens sechsstündigen Moduls des Biergerpakt, des Bürgerpakts für interkulturelles Zusammenleben; Rückerstattung der Anmeldegebühren auf Antrag beim Justizministerium); „Wiedererlangung“ (letztes Datum für Nachkommen: 31. Dezember 2025); „Sprachurlaub“ (200 Stunden im Berufsleben, 2 Teile; keine Alters- oder Wohnsitzbedingung); „Biergerpakt“. Formular „biografische Angaben“: bei den Behörden des Herkunftslandes nachfragen, ob die andere Staatsangehörigkeit erhalten bleibt. Abteilung für die luxemburgische Staatsangehörigkeit im Justizministerium (mj.gouvernement.lu). Nur dauerhafte Angaben: keine Gebühren, keine Telefonnummern, keine Öffnungszeiten, keine Statistiken. Das Wählen erklärt die Folge „Ich kann wählen“. Nur allgemeine Informationen; verbindlich sind allein die Gesetzestexte. Stand: November 2026.*",
 "lb": "*Quellen: guichet.public.lu (Guichet.lu), consultéiert de 27. November 2026 op Englesch an op Franséisch: Nationalitéit duerch d'Gesetz, Naturalisatioun, Optioun, Konditioune virdrun, Erëmerlaangen, Sproochecongé, Biergerpakt; Service vun der lëtzebuergescher Nationalitéit am Justizministère (mj.gouvernement.lu). Keng Gebühren, keng Telefonsnummeren, keng Ëffnungszäiten. Nëmmen allgemeng Informatiounen; nëmmen d'Gesetzestexter sinn bindend. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/nationalite_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 44, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
